@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="container-fluid">
    <div class="row">
        @* Left sidebar — filter panel *@
        <div class="col-3 border-end">
            <ProductFilterPanel Categories="_categories"
                                OnApplyFilters="HandleApplyFilters"
                                OnClearFilters="HandleClearFilters" />
        </div>

        @* Main content area *@
        <div class="col-9">
            @if (_loading)
            {
                <div class="d-flex justify-content-center align-items-center py-5">
                    <div class="spinner-border text-primary" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
            }
            else if (_error is not null)
            {
                <div class="alert alert-danger m-3" role="alert">
                    <strong>Error:</strong> @_error
                </div>
            }
            else
            {
                @* Toolbar *@
                <div class="d-flex justify-content-between align-items-center p-3 border-bottom">
                    <div>
                        <label class="me-2">Sort by:</label>
                        <select class="form-select d-inline-block w-auto" value="@_sortBy" @onchange="HandleSortChanged">
                            <option value="price_asc">Price: Low to High</option>
                            <option value="price_desc">Price: High to Low</option>
                            <option value="name_asc">Name: A-Z</option>
                            <option value="rating_desc">Rating: Highest</option>
                        </select>
                    </div>
                    <span class="text-muted">
                        Showing @(_totalCount == 0 ? "0" : $"{(_currentPage - 1) * PageSize + 1}–{Math.Min(_currentPage * PageSize, _totalCount)}") of @_totalCount products
                    </span>
                </div>

                @* Product grid *@
                @if (_products.Count == 0)
                {
                    <div class="text-center py-5 text-muted">
                        <h5>No products found</h5>
                        <p>Try adjusting your filters.</p>
                    </div>
                }
                else
                {
                    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-3 p-3">
                        @foreach (var product in _products)
                        {
                            <div class="col">
                                <ProductCard Product="product"
                                             OnSelected="HandleProductSelected"
                                             OnAddToCart="HandleAddToCart" />
                            </div>
                        }
                    </div>
                }

                @* Pagination *@
                @if (_totalPages > 1)
                {
                    <div class="py-3">
                        <CatalogPagination CurrentPage="_currentPage"
                                           TotalPages="_totalPages"
                                           OnPageChanged="HandlePageChanged" />
                    </div>
                }
            }
        </div>
    </div>
</div>

@code {
    private const int PageSize = 12;

    private List<string>? _categories;
    private List<Product> _products = new();
    private ProductFilter _currentFilter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private int _totalCount;
    private int _totalPages;
    private bool _loading = true;
    private string? _error;

    /// <summary>Raised when a product card is clicked so the parent can navigate to a detail page.</summary>
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    protected override async Task OnInitializedAsync()
    {
        await LoadCategoriesAndProducts();
    }

    private async Task LoadCategoriesAndProducts()
    {
        _loading = true;
        _error = null;

        try
        {
            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = ProductService.SearchAsync(_currentFilter, _sortBy, _currentPage, PageSize);

            await Task.WhenAll(categoriesTask, productsTask);

            _categories = await categoriesTask;
            var result = await productsTask;
            ApplyResult(result);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task SearchProducts()
    {
        _loading = true;
        _error = null;

        try
        {
            var result = await ProductService.SearchAsync(_currentFilter, _sortBy, _currentPage, PageSize);
            ApplyResult(result);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private void ApplyResult(PagedResult<Product> result)
    {
        _products = result.Items;
        _totalCount = result.TotalCount;
        _totalPages = (int)Math.Ceiling((double)result.TotalCount / PageSize);
    }

    private async Task HandleApplyFilters(ProductFilter filter)
    {
        _currentFilter = filter;
        _currentPage = 1;
        await SearchProducts();
    }

    private async Task HandleClearFilters()
    {
        _currentFilter = new ProductFilter(null, null, null, false);
        _currentPage = 1;
        await SearchProducts();
    }

    private async Task HandleSortChanged(ChangeEventArgs e)
    {
        _sortBy = e.Value?.ToString() ?? "price_asc";
        _currentPage = 1;
        await SearchProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await SearchProducts();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder — cart functionality would be handled by a cart service
        return Task.CompletedTask;
    }
}
"}

